let bsd_width = 5;
match (options.algo_name, not_file) {
    (ALGORITHM_OPTIONS_SYSV, true) => print_checksum_line(
        &format!(
            "{} {}",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        None,
        "",
    )?,
    (ALGORITHM_OPTIONS_SYSV, false) => print_checksum_line(
        &format!(
            "{} {} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        Some(filename),
        "",
    )?,
    (ALGORITHM_OPTIONS_BSD, true) => print_checksum_line(
        &format!(
            "{:0bsd_width$} {:bsd_width$}",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        None,
        "",
    )?,
    (ALGORITHM_OPTIONS_BSD, false) => print_checksum_line(
        &format!(
            "{:0bsd_width$} {:bsd_width$} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        Some(filename),
        "",
    )?,
    (ALGORITHM_OPTIONS_CRC, true) => {
        print_checksum_line(&format!("{sum} {sz}"), None, "")?
    }
    (ALGORITHM_OPTIONS_CRC, false) => {
        print_checksum_line(&format!("{sum} {sz} "), Some(filename), "")?
    }
    (ALGORITHM_OPTIONS_BLAKE2B, _) if options.tag => {
        if let Some(length) = options.length {
            // Multiply by 8 here, as we want to print the length in bits.
            print_checksum_line(
                &format!("BLAKE2b-{} (", length * 8),
                Some(filename),
                &format!(") = {sum}"),
            )?;
        } else {
            print_checksum_line("BLAKE2b (", Some(filename), &format!(") = {sum}"))?;
        }
    }
    _ => {
        if options.tag {
            print_checksum_line(
                &format!("{} (", options.algo_name.to_ascii_uppercase()),
                Some(filename),
                &format!(") = {sum}"),
            )?;
        } else {
            let prefix = if options.asterisk { "*" } else { " " };
            print_checksum_line(
                &format!("{sum} {prefix}"),
                Some(filename),
                "",
            )?;
        }
    }
}

struct Options {
    algo_name: &'static str,
    digest: Box<dyn Digest + 'static>,
    output_bits: usize,
    tag: bool, // will cover the --untagged option
    length: Option<usize>,
    output_format: OutputFormat,
    asterisk: bool, // if we display an asterisk or not (--binary/--text)
}

fn print_checksum_line(prefix: &str, filename: Option<&Path>, suffix: &str) -> io::Result<()> {
    print_verbatim(prefix)?;
    if let Some(filename) = filename {
        print_verbatim(filename)?;
    }
    println_verbatim(suffix)
}

